//! ₂F₁(a, b; c; z) where its series' terms change sign and the sum cancels (negative or polynomial parameters, c
//! below a or b), against 60-digit values (`fixtures/hyp2f1_cancellation.json`, generated by
//! `fixtures/hyp2f1_cancellation.py` with mpmath), including the cases a review found off by up to 3e-3.

use keanu_tensor::special::{hyp2f1, hyp2f1_dz};
use serde_json::Value;

/// Cases outside the documented accuracy, with the reason (each named in [`hyp2f1`]'s documentation).
const EXCEPTIONS: &[([f64; 4], &str)] = &[(
    [-21.0, 5.03, 1.03, 0.999],
    "a polynomial within rounding of a degenerate case: b − c − m + 1 = −16 (to rounding) with m = 21",
)];

#[test]
fn hyp2f1_keeps_its_accuracy_where_the_series_cancels() {
    let fixture: Value =
        serde_json::from_str(include_str!("fixtures/hyp2f1_cancellation.json")).unwrap();
    let cases = fixture["cases"].as_array().unwrap();
    assert!(cases.len() > 800);
    let mut failures = Vec::new();
    let mut worst = 0.0f64;
    for case in cases {
        let x: Vec<f64> = case["x"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap())
            .collect();
        let (a, b, c, z) = (x[0], x[1], x[2], x[3]);
        if EXCEPTIONS.iter().any(|(e, _)| e == &[a, b, c, z]) {
            continue;
        }
        let expected = case["v"].as_f64().unwrap();
        let actual = hyp2f1(a, b, c, z);
        let error = (actual - expected).abs() / expected.abs().max(1e-300);
        worst = worst.max(error);
        // the documented bound: 1e-14 for −1 <= z < 0.999, 5e-14 elsewhere
        let tolerance = if (-1.0..0.999).contains(&z) {
            1e-14
        } else {
            5e-14
        };
        if error.is_nan() || error > tolerance {
            failures.push(format!(
                "hyp2f1({a}, {b}, {c}, {z}) = {actual:e}, expected {expected:e} (error {error:.1e})"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} failures (worst {worst:.1e}):\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn hyp2f1_dz_is_the_shifted_function() {
    // the derivative is (ab/c) ₂F₁(a + 1, b + 1; c + 1; z), so it is as accurate as the function on cancelling
    // parameters too
    for (a, b, c, z) in [
        (25.0, 25.0, 0.3, -1.0),
        (-10.0, 5.0, 2.5, 0.99),
        (-23.8, 23.32, 5.42, 0.786),
    ] {
        assert_eq!(
            hyp2f1_dz(a, b, c, z),
            a * b / c * hyp2f1(a + 1.0, b + 1.0, c + 1.0, z)
        );
    }
}
